	--eq.spawn2(280091,0,0,1451.65,957.84,517.86,432);
end

function RC_Timer(e)
	if(e.timer=="depop") then
		eq.stop_timer("depop");
		eq.depop();
		eq.depop_all(280069);
		eq.depop_all(280091);
	end
end

function Jugg_Spawn(e)
	eq.set_timer("depop",15*60*1000);
end

function Jugg_Combat(e)
	if e.joined then		
		eq.set_timer("conduit",7*1000); --Energy Conduit:
		eq.set_timer("checkleash",1*1000);
	else
		eq.stop_timer("conduit");
		eq.stop_timer("checkleash");
	end
end

function Jugg_Timer(e)
	if(e.timer=="depop") then
		eq.stop_timer("depop");
		eq.depop();
		eq.depop_all(280069);
		eq.depop_all(280090);
	elseif (e.timer=="conduit") then
		eq.stop_timer("conduit");
		e.self:CastSpell(5800, e.self:GetHateTop():GetID()); -- Spell: Energy Conduit
		eq.set_timer("conduit",20*1000);
	elseif (e.timer == "checkleash") then
		if (e.self:CalculateDistance(1451,957,517) > 95) then
			e.self:GotoBind()
			e.self:SetHP(e.self:GetMaxHP())
			e.self:CastSpell(3791, e.self:GetID())
			e.self:WipeHateList();
		end
	end
end

function Reborn_Death(e)
	if not eq.get_entity_list():IsMobSpawnedByNpcTypeID(280069) then
		eq.spawn2(280091,0,0,1451.65,957.84,517.86,432); -- NPC: #Noc_Juggernaut
		eq.depop_all(280090);
	end
end


function event_encounter_load(e)
  eq.register_npc_event('druid_1_5', Event.timer,          280090, RC_Timer); 
  eq.register_npc_event('druid_1_5', Event.spawn,          280090, RC_Spawn);
  eq.register_npc_event('druid_1_5', Event.combat,         280091, Jugg_Combat);   
  eq.register_npc_event('druid_1_5', Event.timer,         	280091, Jugg_Timer);
  eq.register_npc_event('druid_1_5', Event.spawn,         	280091, Jugg_Spawn);
  eq.register_npc_event('druid_1_5', Event.death_complete,  280069, Reborn_Death); 
end

function event_say(e)
	if(e.message:findi("Hail")) then
		e.self:Say("Good day to you, " .. e.other:GetName() .. ". Are you a shaman of [much experience]?");
	elseif(e.message:findi("much experience")) then
		e.self:Say("Then welcome to the tests of the medicine man. I have two tomes, each tells of a shaman of great accomplishment. They are Gina MacStargan and Ooga. Simply tell me the name of the shaman you want to be tested by.");
	elseif((e.message:findi("Gina MacStargan")) and (e.other:Class() == "Shaman")) then
		e.self:Say("I shall summon them for you");
		eq.spawn2(71087,0,0,631.9,1401.9,-766.9,259.6); -- NPC: Gina_McStargan
		eq.depop_with_timer();
	elseif((e.message:findi("Ooga")) and (e.other:Class() == "Shaman")) then
		e.self:Say("I shall summon them for you");
		eq.spawn2(71093,0,0,653.4,1399.0,-766.9,259.6); -- NPC: Ooga
		eq.depop_with_timer();
	end
end

